#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>
#include <zephyr/video/video_buffer.h>
#include <zephyr/sys/slist.h>
#include <string.h>

LOG_MODULE_REGISTER(video_buffer, CONFIG_VIDEO_BUFFER_LOG_LEVEL);

#define MAX_VIDEO_BUFFERS CONFIG_VIDEO_BUFFER_MAX_BUFFERS
#define VIDEO_BUFFER_DATA_SIZE CONFIG_VIDEO_BUFFER_DATA_SIZE

/* Static pool of video_buffer structures */
static struct video_buffer video_buffers[MAX_VIDEO_BUFFERS];
/* Static memory for video data (simple contiguous block) */
static uint8_t video_data_pool[MAX_VIDEO_BUFFERS * VIDEO_BUFFER_DATA_SIZE];

static K_MUTEX_DEFINE(video_buffer_mutex);
static sys_slist_t free_buffers;

/* Helper to get buffer index for logging/validation */
static int get_buffer_idx(struct video_buffer *buffer)
{
    if (buffer == NULL || buffer < &video_buffers[0] || buffer >= &video_buffers[MAX_VIDEO_BUFFERS]) {
        return -1;
    }
    return (int)(buffer - &video_buffers[0]);
}

void video_buffer_init(void)
{
    k_mutex_lock(&video_buffer_mutex, K_FOREVER);

    sys_slist_init(&free_buffers);
    for (int i = 0; i < MAX_VIDEO_BUFFERS; i++) {
        video_buffers[i].index = i;
        video_buffers[i].size = VIDEO_BUFFER_DATA_SIZE;
        video_buffers[i].data = &video_data_pool[i * VIDEO_BUFFER_DATA_SIZE];
        video_buffers[i].bytesused = 0;
        video_buffers[i].flags = VIDEO_BUFFER_FLAG_FREE;
        sys_slist_append(&free_buffers, &video_buffers[i].node);
    }
    LOG_DBG("Video buffer pool initialized with %d buffers, each %u bytes",
            MAX_VIDEO_BUFFERS, VIDEO_BUFFER_DATA_SIZE);

    k_mutex_unlock(&video_buffer_mutex);
}

struct video_buffer *video_buffer_alloc(size_t size)
{
    struct video_buffer *buffer = NULL;

    if (size > VIDEO_BUFFER_DATA_SIZE) {
        LOG_ERR("Requested buffer size %zu exceeds max buffer data size %u",
                size, VIDEO_BUFFER_DATA_SIZE);
        return NULL;
    }

    k_mutex_lock(&video_buffer_mutex, K_FOREVER);

    sys_snode_t *node = sys_slist_get(&free_buffers);
    if (node != NULL) {
        buffer = CONTAINER_OF(node, struct video_buffer, node);
        /* Ensure the buffer is marked as not free and clear other flags */
        buffer->flags &= ~VIDEO_BUFFER_FLAG_FREE;
        buffer->bytesused = 0; /* Reset bytes used on allocation */
        /* The 'data' pointer and 'size' (max capacity) are fixed per buffer in this pool */
        LOG_DBG("Allocated buffer %d (data_ptr: %p, capacity: %zu)",
                buffer->index, buffer->data, buffer->size);
    } else {
        LOG_ERR("No free video buffers available");
    }

    k_mutex_unlock(&video_buffer_mutex);
    return buffer;
}

int video_buffer_release(struct video_buffer *buffer)
{
    /* FIX: Add NULL pointer check to prevent segmentation fault */
    if (buffer == NULL) {
        LOG_ERR("Attempted to release a NULL video buffer");
        return -EINVAL;
    }

    k_mutex_lock(&video_buffer_mutex, K_FOREVER);

    int idx = get_buffer_idx(buffer);
    if (idx == -1) {
        LOG_ERR("Invalid video buffer pointer: %p. Not part of the pool.", buffer);
        k_mutex_unlock(&video_buffer_mutex);
        return -EINVAL;
    }

    if (buffer->flags & VIDEO_BUFFER_FLAG_FREE) {
        LOG_ERR("Buffer %d is already released", idx);
        k_mutex_unlock(&video_buffer_mutex);
        return -EALREADY;
    }

    /* Clear data for security/debug purposes (optional) */
    /* memset(buffer->data, 0, buffer->size); */
    buffer->bytesused = 0;
    buffer->flags |= VIDEO_BUFFER_FLAG_FREE;
    sys_slist_append(&free_buffers, &buffer->node);
    LOG_DBG("Released buffer %d", idx);

    k_mutex_unlock(&video_buffer_mutex);
    return 0;
}
